-- Identity columns: continue after the loaded rows.
begin
    for t in (select table_name, column_name from user_tab_identity_cols
               where table_name like 'ORB\_%' escape '\') loop
        execute immediate 'alter table ' || t.table_name || ' modify ' || t.column_name
                       || ' generated by default on null as identity (start with limit value)';
    end loop;
end;
/

